@Entity
@SequenceGenerator(
    name = "member_seq_generator",
    sequenceName = "MEMBER_SEQ",   // DB 에 만들어질 시퀀스 이름
    initialValue = 1,
    allocationSize = 50            // 기본값. 아래에서 설명
)
public class Member {

    @Id
    @GeneratedValue(strategy = GenerationType.SEQUENCE,
                    generator = "member_seq_generator")
    private Long id;
}

@Entity
@TableGenerator(
    name = "member_seq_generator",
    table = "MY_SEQUENCES",
    pkColumnValue = "MEMBER_SEQ",
    allocationSize = 50
)
public class Member {

    @Id
    @GeneratedValue(strategy = GenerationType.TABLE,
                    generator = "member_seq_generator")
    private Long id;
}

